rulesets.ast-strictness-and-unsupported-casts:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /boolCast/{doc} {
      allow read: if bool('true') == true;
    }
    match /mathInfinite/{doc} {
      allow write: if math.isInfinite(1.0);
    }
    match /mapHasAll/{doc} {
      allow delete: if request.resource.data.hasAll(['required_key']);
      allow create: if request.resource.data.keys().hasAll(['required_key']);
    }
  }
}

rulesets.atomic-batch-sibling-merge:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /auditLogs/{logId} {
      allow create: if request.auth != null
                    && getAfter(/databases/$(database)/documents/config/state).data.role == 'admin'
                    && getAfter(/databases/$(database)/documents/config/state).data.modified == true;
    }
    match /config/{docId} {
      allow update: if request.auth != null;
    }
  }
}

rulesets.builtins-time-and-math:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // 1. math.abs() — bounded delta validation.
    match /scoresAllow/{id} {
      allow create: if request.auth != null
        && math.abs(request.resource.data.delta) <= 100;
    }
    match /scoresDeny/{id} {
      allow create: if request.auth != null
        && math.abs(request.resource.data.delta) <= 100;
    }

    // 2. math.ceil() — round-up bound check.
    match /pricingAllow/{id} {
      allow create: if request.auth != null
        && math.ceil(request.resource.data.price) <= 100;
    }
    match /pricingDeny/{id} {
      allow create: if request.auth != null
        && math.ceil(request.resource.data.price) <= 100;
    }

    // 3. timestamp.date() — pure literal comparison, no request.time.
    match /datesAllow/{id} {
      allow create: if request.auth != null
        && timestamp.date(2099, 1, 1) > timestamp.date(2025, 1, 1);
    }
    match /datesDeny/{id} {
      allow create: if request.auth != null
        && timestamp.date(2025, 1, 1) > timestamp.date(2099, 1, 1);
    }

    // 4. duration.value() — pure duration comparison, no request.time.
    match /durAllow/{id} {
      allow create: if request.auth != null
        && duration.value(2, 'h') > duration.value(1, 'h');
    }
    match /durDeny/{id} {
      allow create: if request.auth != null
        && duration.value(1, 'h') > duration.value(2, 'h');
    }
  }
}

rulesets.bytes-toutf8-and-hashing:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // toUtf8 → Bytes, .size() returns byte count
    match /utf8SizeAllow/{id} {
      allow create: if request.auth != null
        && 'hello'.toUtf8().size() == 5;
    }
    // multi-byte UTF-8 length
    match /utf8MultibyteAllow/{id} {
      allow create: if request.auth != null
        && 'é'.toUtf8().size() == 2;
    }
    // toBase64 round-trip (no padding, URL-safe)
    match /base64Allow/{id} {
      allow create: if request.auth != null
        && 'hi'.toUtf8().toBase64() == 'aGk';
    }
    // toHexString round-trip
    match /hexAllow/{id} {
      allow create: if request.auth != null
        && 'hi'.toUtf8().toHexString() == '6869';
    }
    // is bytes
    match /isBytesAllow/{id} {
      allow create: if request.auth != null
        && 'x'.toUtf8() is bytes;
    }
    // md5 of empty string — well-known reference
    match /md5EmptyAllow/{id} {
      allow create: if request.auth != null
        && hashing.md5('').toHexString() == 'd41d8cd98f00b204e9800998ecf8427e';
    }
    // sha256 of 'abc' — NIST FIPS 180-4 reference
    match /sha256AbcAllow/{id} {
      allow create: if request.auth != null
        && hashing.sha256('abc').toHexString() == 'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad';
    }
    // crc32 reference (IEEE 802.3, '123456789' → 0xCBF43926)
    match /crc32RefAllow/{id} {
      allow create: if request.auth != null
        && hashing.crc32('123456789').toHexString() == 'cbf43926';
    }
    // crc32c reference (Castagnoli, '123456789' → 0xE3069283)
    match /crc32cRefAllow/{id} {
      allow create: if request.auth != null
        && hashing.crc32c('123456789').toHexString() == 'e3069283';
    }
    // hashing accepts pre-encoded Bytes too
    match /hashAcceptsBytesAllow/{id} {
      allow create: if request.auth != null
        && hashing.md5('hello'.toUtf8()) == hashing.md5('hello');
    }
    // Production Bytes encodings preserve base64url padding and use uppercase
    // hexadecimal output. These positive witnesses distinguish representation
    // fidelity from merely denying the historical lowercase/unpadded cases.
    match /base64PaddedAllow/{id} {
      allow create: if request.auth != null
        && 'hi'.toUtf8().toBase64() == 'aGk=';
    }
    match /base64UrlAlphabetAllow/{id} {
      allow create: if request.auth != null
        && '~~~'.toUtf8().toBase64() == 'fn5-';
    }
    match /base64StandardAlphabetDeny/{id} {
      allow create: if request.auth != null
        && '~~~'.toUtf8().toBase64() == 'fn5+';
    }
    match /md5UpperAllow/{id} {
      allow create: if request.auth != null
        && hashing.md5('').toHexString() == 'D41D8CD98F00B204E9800998ECF8427E';
    }
    match /sha256UpperAllow/{id} {
      allow create: if request.auth != null
        && hashing.sha256('abc').toHexString() == 'BA7816BF8F01CFEA414140DE5DAE2223B00361A396177A9CB410FF61F20015AD';
    }
    match /crc32UpperAllow/{id} {
      allow create: if request.auth != null
        && hashing.crc32('123456789').toHexString() == 'CBF43926';
    }
    match /crc32cUpperAllow/{id} {
      allow create: if request.auth != null
        && hashing.crc32c('123456789').toHexString() == 'E3069283';
    }
    match /crc32LittleEndianAllow/{id} {
      allow create: if request.auth != null
        && hashing.crc32('123456789').toHexString() == '2639F4CB';
    }
    match /crc32cLittleEndianAllow/{id} {
      allow create: if request.auth != null
        && hashing.crc32c('123456789').toHexString() == '839206E3';
    }
    // Multi-block, padding-boundary, Bytes, and non-ASCII digests. Each
    // expected value is the uppercase hexadecimal digest of the UTF-8 input.
    match /md5TwoBlockAllow/{id} {
      allow create: if request.auth != null
        && hashing.md5('12345678901234567890123456789012345678901234567890123456789012345678901234567890').toHexString() == '57EDF4A22BE3C955AC49DA2E2107B67A';
    }
    match /md5FiftyFiveBytesAllow/{id} {
      allow create: if request.auth != null
        && hashing.md5('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx').toHexString() == '04364420E25C512FD958A70738AA8F72';
    }
    match /md5FiftySixBytesAllow/{id} {
      allow create: if request.auth != null
        && hashing.md5('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx').toHexString() == '668A72D5BA17F08E62DABCAFAD6DB14B';
    }
    match /md5SixtyFourBytesInputAllow/{id} {
      allow create: if request.auth != null
        && hashing.md5('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'.toUtf8()).toHexString() == '014842D480B571495A4A0363793F7367';
    }
    match /md5NonAsciiAllow/{id} {
      allow create: if request.auth != null
        && hashing.md5('naïve café 日本語').toHexString() == '2204EF5849F3257174545026F61FFD01';
    }
    match /sha256FiftySixBytesAllow/{id} {
      allow create: if request.auth != null
        && hashing.sha256('abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq').toHexString() == '248D6A61D20638B8E5C026930C3E6039A33CE45964FF2167F6ECEDD419DB06C1';
    }
    match /sha256OneTwelveBytesAllow/{id} {
      allow create: if request.auth != null
        && hashing.sha256('abcdefghbcdefghicdefghijdefghijkefghijklfghijklmghijklmnhijklmnoijklmnopjklmnopqklmnopqrlmnopqrsmnopqrstnopqrstu').toHexString() == 'CF5B16A778AF8380036CE59E7B0492370B249B11E8F07A51AFAC45037AFEE9D1';
    }
    match /sha256OneTwentyBytesInputAllow/{id} {
      allow create: if request.auth != null
        && hashing.sha256('xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'.toUtf8()).toHexString() == '13F05A0B594787F5ECD315EDC96141BD3243203D1B7D4F0836F37308B276BA98';
    }
    match /sha256NonAsciiAllow/{id} {
      allow create: if request.auth != null
        && hashing.sha256('naïve café 日本語').toHexString() == '7EDCE543470723527A9A231BD4C4EFA1B626CE8232318DCB1AA1AE9B43766867';
    }
    // DENY witness — wrong digest
    match /md5WrongDeny/{id} {
      allow create: if request.auth != null
        && hashing.md5('hello').toHexString() == 'deadbeef';
    }
    match /bytesLiteral/equalsToUtf8/{id} {
      allow create: if b'abc' == 'abc'.toUtf8();
    }
    match /bytesLiteral/doubleQuoted/{id} {
      allow create: if b"abc" == 'abc'.toUtf8() && b"it's" == 'it\'s'.toUtf8();
    }
    match /bytesLiteral/upperPrefix/{id} {
      allow create: if B'abc' == b"abc";
    }
    match /bytesLiteral/emptyLiteral/{id} {
      allow create: if b''.size() == 0 && b'' == ''.toUtf8();
    }
    match /bytesLiteral/hexEscapeSize/{id} {
      allow create: if b'\x00\x01'.size() == 2;
    }
    match /bytesLiteral/hexEscapeNotText/{id} {
      allow create: if b'\x00\x01'.size() == 8;
    }
    match /bytesLiteral/hexEscapeValue/{id} {
      allow create: if b'\x00\x01'.toHexString() == '0001' && b'\xFf\xfF'.toHexString() == 'FFFF';
    }
    match /bytesLiteral/hexEscapeTwoDigits/{id} {
      allow create: if b'\x411' == b'A1';
    }
    match /bytesLiteral/octalEscape/{id} {
      allow create: if b'\101' == 'A'.toUtf8() && b'\012' == b'\n' && b'\377' == b'\xff';
    }
    match /bytesLiteral/simpleEscapes/{id} {
      allow create: if b'\\\'\"\n\r\t\b\f'.toHexString() == '5C27220A0D09080C';
    }
    match /bytesLiteral/nonAsciiUtf8/{id} {
      allow create: if b'é' == 'é'.toUtf8() && b'é' == b'\xc3\xa9' && b'日本'.size() == 6;
    }
    match /bytesLiteral/highByteNotUtf8/{id} {
      allow create: if b'\xe9' == 'é'.toUtf8();
    }
    match /bytesLiteral/isBytes/{id} {
      allow create: if b'abc' is bytes;
    }
    match /bytesLiteral/toBase64/{id} {
      allow create: if b'\xff'.toBase64() == '_w==';
    }
    match /bytesLiteral/notEqualString/{id} {
      allow create: if b'abc' == 'abc';
    }
    match /bytesLiteral/notEqualBytes/{id} {
      allow create: if b'abc' == b'abd';
    }
    match /bytesLiteral/ordering/{id} {
      allow create: if b'abc' < b'abd' && b'abc' > b'ab' && b'\x00' < b'\xff';
    }
    match /bytesLiteral/inList/{id} {
      allow create: if b'abc' in [b'abc'] && !(b'abd' in [b'abc']);
    }
    match /bytesLiteral/hashing/{id} {
      allow create: if hashing.md5(b'abc') == hashing.md5('abc');
    }
    match /bytesLiteral/concatError/{id} {
      allow create: if b'abc' + b'd' == b'abcd';
    }
    match /bytesLiteral/concatErrorOrTrue/{id} {
      allow create: if (b'abc' + b'd' == b'abcd') || true;
    }
    match /bytesLiteral/indexError/{id} {
      allow create: if b'abc'[0] == 97;
    }
  }
}

rulesets.common-auth-membership-firestore:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isAuthenticated() {
      return request.auth != null;
    }
    function isOwner(userId) {
      return isAuthenticated() && request.auth.uid == userId;
    }
    function hasClaim(claim) {
      return request.auth != null && request.auth.token[claim] != null;
    }
    function hasClaimRole(claim, role) {
      return request.auth != null && request.auth.token[claim] == role;
    }
    function isMemberOf(membersMap) {
      return request.auth != null && request.auth.uid in membersMap;
    }
    function hasRole(membersMap, role) {
      return request.auth != null && membersMap[request.auth.uid] == role;
    }

    match /authenticated/{fileId} {
      allow create: if isAuthenticated();
    }
    match /owners/{ownerId} {
      allow create: if isOwner(ownerId);
    }
    match /claims/{fileId} {
      allow create: if hasClaim('plan');
    }
    match /claim-roles/{fileId} {
      allow create: if hasClaimRole('role', 'editor');
    }
    match /members/{fileId} {
      allow create: if isMemberOf(request.auth.token.members);
    }
    match /member-roles/{fileId} {
      allow create: if hasRole(request.auth.token.members, 'editor');
    }
  }
}

rulesets.cross-type-operator-overloads:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // Timestamp + Duration → Timestamp
    match /tsPlusDurAllow/{id} {
      allow create: if request.auth != null
        && timestamp.value(0) + duration.value(60, 's') == timestamp.value(60000);
    }
    // Timestamp - Duration → Timestamp
    match /tsMinusDurAllow/{id} {
      allow create: if request.auth != null
        && timestamp.value(60000) - duration.value(60, 's') == timestamp.value(0);
    }
    // Timestamp - Timestamp → Duration
    match /tsMinusTsAllow/{id} {
      allow create: if request.auth != null
        && timestamp.value(60000) - timestamp.value(0) == duration.value(60, 's');
    }
    // Duration + Duration → Duration
    match /durPlusDurAllow/{id} {
      allow create: if request.auth != null
        && duration.value(30, 's') + duration.value(30, 's') == duration.value(60, 's');
    }
    // Duration - Duration → Duration
    match /durMinusDurAllow/{id} {
      allow create: if request.auth != null
        && duration.value(60, 's') - duration.value(30, 's') == duration.value(30, 's');
    }
    // Timestamp comparison via field-wise compareTo (not numeric coercion)
    match /tsLessThanAllow/{id} {
      allow create: if request.auth != null
        && timestamp.date(2025, 1, 1) < timestamp.date(2099, 1, 1);
    }
    // DENY witness — wrong arithmetic should still fail
    match /tsPlusDurDeny/{id} {
      allow create: if request.auth != null
        && timestamp.value(0) + duration.value(60, 's') == timestamp.value(0);
    }
    match /plusOperand/listLiteralEq/{id} {
      allow create: if [1] + [2] == [1, 2];
    }
    match /plusOperand/listLiteralNeq/{id} {
      allow create: if [1] + [2] != [9];
    }
    match /plusOperand/listLiteralOrTrue/{id} {
      allow create: if ([1] + [2] == [1, 2]) || true;
    }
    match /plusOperand/listDataEq/{id} {
      allow create: if request.resource.data.a + request.resource.data.b == ['a', 'b', 'c', 'd'];
    }
    match /plusOperand/listDataNeq/{id} {
      allow create: if request.resource.data.a + request.resource.data.b != ['z'];
    }
    match /plusOperand/listDataOrTrue/{id} {
      allow create: if (request.resource.data.a + request.resource.data.b == ['a', 'b', 'c', 'd']) || true;
    }
    match /plusOperand/listStringNeq/{id} {
      allow create: if request.resource.data.a + request.resource.data.s != ['z'];
    }
    match /plusOperand/listStringOrTrue/{id} {
      allow create: if (request.resource.data.a + request.resource.data.s != ['z']) || true;
    }
    match /plusOperand/stringListNeq/{id} {
      allow create: if request.resource.data.s + request.resource.data.a != 'z';
    }
    match /plusOperand/stringListOrTrue/{id} {
      allow create: if (request.resource.data.s + request.resource.data.a != 'z') || true;
    }
    match /plusOperand/stringIntNeq/{id} {
      allow create: if request.resource.data.s + request.resource.data.n != 'z';
    }
    match /plusOperand/stringIntOrTrue/{id} {
      allow create: if (request.resource.data.s + request.resource.data.n != 'z') || true;
    }
    match /plusOperand/stringIntLiteralNeq/{id} {
      allow create: if 'a' + 1 != 'x';
    }
    match /plusOperand/intStringNeq/{id} {
      allow create: if request.resource.data.n + request.resource.data.s != 'z';
    }
    match /plusOperand/intStringOrTrue/{id} {
      allow create: if (request.resource.data.n + request.resource.data.s != 'z') || true;
    }
    match /plusOperand/mapMapNeq/{id} {
      allow create: if request.resource.data.m + {'b': 'c'} != {};
    }
    match /plusOperand/mapMapOrTrue/{id} {
      allow create: if (request.resource.data.m + {'b': 'c'} != {}) || true;
    }
    match /plusOperand/stringStringEq/{id} {
      allow create: if request.resource.data.s + '/x' == 'ab/x' && 'a' + 'b' == 'ab';
    }
    match /plusOperand/stringStringNeq/{id} {
      allow create: if request.resource.data.s + 'c' != 'abc';
    }
    match /plusOperand/stringStringOrTrue/{id} {
      allow create: if (request.resource.data.s + 'c' != 'abc') || true;
    }
    match /plusOperand/intFloatEq/{id} {
      allow create: if request.resource.data.n + 1.5 == 4.5 && 1.5 + 1 == 2.5;
    }
    match /plusOperand/intFloatNeq/{id} {
      allow create: if request.resource.data.n + 1.5 != 4.5;
    }
    match /plusOperand/intFloatOrTrue/{id} {
      allow create: if (request.resource.data.n + 1.5 != 4.5) || true;
    }
    match /plusOperand/concatDataEq/{id} {
      allow create: if request.resource.data.a.concat(request.resource.data.b) == ['a', 'b', 'c', 'd'];
    }
    match /plusOperand/concatLiteralEq/{id} {
      allow create: if [1].concat([2]) == [1, 2];
    }
    match /plusOperand/concatLiteralNeq/{id} {
      allow create: if [1].concat([2]) != [1, 2];
    }
    match /plusOperand/stringTimestampBare/{id} {
      allow create: if 'at ' + timestamp.value(0);
    }
    match /plusOperand/stringTimestampNeq/{id} {
      allow create: if 'at ' + timestamp.value(0) != 'z';
    }
    match /plusOperand/stringTimestampOrTrue/{id} {
      allow create: if ('at ' + timestamp.value(0) != 'z') || true;
    }
    match /plusOperand/stringRequestTimeBare/{id} {
      allow create: if 'at ' + request.time;
    }
    match /plusOperand/stringRequestTimeNeq/{id} {
      allow create: if 'at ' + request.time != 'z';
    }
    match /plusOperand/stringRequestTimeOrTrue/{id} {
      allow create: if ('at ' + request.time != 'z') || true;
    }
    match /plusOperand/timestampStringBare/{id} {
      allow create: if timestamp.value(0) + ' at';
    }
    match /plusOperand/timestampStringNeq/{id} {
      allow create: if timestamp.value(0) + ' at' != 'z';
    }
    match /plusOperand/timestampStringOrTrue/{id} {
      allow create: if (timestamp.value(0) + ' at' != 'z') || true;
    }
    match /plusOperand/stringDurationBare/{id} {
      allow create: if 'for ' + duration.value(60, 's');
    }
    match /plusOperand/stringDurationNeq/{id} {
      allow create: if 'for ' + duration.value(60, 's') != 'z';
    }
    match /plusOperand/stringDurationOrTrue/{id} {
      allow create: if ('for ' + duration.value(60, 's') != 'z') || true;
    }
    match /plusOperand/durationStringBare/{id} {
      allow create: if duration.value(60, 's') + ' later';
    }
    match /plusOperand/durationStringNeq/{id} {
      allow create: if duration.value(60, 's') + ' later' != 'z';
    }
    match /plusOperand/durationStringOrTrue/{id} {
      allow create: if (duration.value(60, 's') + ' later' != 'z') || true;
    }
    match /plusOperand/timestampTimestampBare/{id} {
      allow create: if timestamp.value(0) + timestamp.value(60000);
    }
    match /plusOperand/timestampTimestampNeq/{id} {
      allow create: if timestamp.value(0) + timestamp.value(60000) != timestamp.value(1);
    }
    match /plusOperand/timestampTimestampOrTrue/{id} {
      allow create: if (timestamp.value(0) + timestamp.value(60000) != timestamp.value(1)) || true;
    }
    match /plusOperand/stringBytesBare/{id} {
      allow create: if 'a' + 'b'.toUtf8();
    }
    match /plusOperand/stringBytesNeq/{id} {
      allow create: if 'a' + 'b'.toUtf8() != 'z';
    }
    match /plusOperand/stringBytesOrTrue/{id} {
      allow create: if ('a' + 'b'.toUtf8() != 'z') || true;
    }
    match /plusOperand/bytesStringBare/{id} {
      allow create: if 'a'.toUtf8() + 'b';
    }
    match /plusOperand/bytesStringNeq/{id} {
      allow create: if 'a'.toUtf8() + 'b' != 'z';
    }
    match /plusOperand/bytesStringOrTrue/{id} {
      allow create: if ('a'.toUtf8() + 'b' != 'z') || true;
    }
    match /plusOperand/bytesBytesBare/{id} {
      allow create: if 'ab'.toUtf8() + 'cd'.toUtf8();
    }
    match /plusOperand/bytesBytesNeq/{id} {
      allow create: if 'ab'.toUtf8() + 'cd'.toUtf8() != 'zz'.toUtf8();
    }
    match /plusOperand/bytesBytesOrTrue/{id} {
      allow create: if ('ab'.toUtf8() + 'cd'.toUtf8() != 'zz'.toUtf8()) || true;
    }
    match /plusOperand/durationIntBare/{id} {
      allow create: if duration.value(60, 's') + 1;
    }
    match /plusOperand/durationIntNeq/{id} {
      allow create: if duration.value(60, 's') + 1 != duration.value(1, 's');
    }
    match /plusOperand/durationIntOrTrue/{id} {
      allow create: if (duration.value(60, 's') + 1 != duration.value(1, 's')) || true;
    }
    match /plusOperand/intDurationBare/{id} {
      allow create: if 1 + duration.value(60, 's');
    }
    match /plusOperand/intDurationNeq/{id} {
      allow create: if 1 + duration.value(60, 's') != duration.value(1, 's');
    }
    match /plusOperand/intDurationOrTrue/{id} {
      allow create: if (1 + duration.value(60, 's') != duration.value(1, 's')) || true;
    }
    match /plusOperand/bytesBytesEq/{id} {
      allow create: if 'ab'.toUtf8() + 'cd'.toUtf8() == 'abcd'.toUtf8();
    }
    match /equalityIdentity/0/{id} {
      allow create: if 1 == 1.0;
    }
    match /equalityIdentity/1/{id} {
      allow create: if [1] == [1.0];
    }
    match /equalityIdentity/2/{id} {
      allow create: if [1] != [1.0];
    }
    match /equalityIdentity/3/{id} {
      allow create: if [1.0] == [1];
    }
    match /equalityIdentity/4/{id} {
      allow create: if [1, 2] == [1, 2.0];
    }
    match /equalityIdentity/5/{id} {
      allow create: if [[1]] == [[1.0]];
    }
    match /equalityIdentity/6/{id} {
      allow create: if {'a': 1} == {'a': 1.0};
    }
    match /equalityIdentity/7/{id} {
      allow create: if {'a': 1} != {'a': 1.0};
    }
    match /equalityIdentity/8/{id} {
      allow create: if {'a': [1]} == {'a': [1.0]};
    }
    match /equalityIdentity/9/{id} {
      allow create: if [1][0] == 1.0;
    }
    match /equalityIdentity/10/{id} {
      allow create: if {'a': 1}.a == 1.0;
    }
    match /equalityIdentity/11/{id} {
      allow create: if [1.0] == [1.0];
    }
    match /equalityIdentity/12/{id} {
      allow create: if {'a': 1.0} == {'a': 1.0};
    }
    match /equalityIdentity/13/{id} {
      allow create: if 0 == -0.0;
    }
    match /equalityIdentity/14/{id} {
      allow create: if [0.0] == [-0.0];
    }
    match /equalityIdentity/15/{id} {
      allow create: if [-0.0] == [-0.0];
    }
    match /equalityIdentity/16/{id} {
      allow create: if {'a': -0.0} == {'a': 0.0};
    }
    match /equalityIdentity/17/{id} {
      allow create: if float('NaN') == float('NaN');
    }
    match /equalityIdentity/18/{id} {
      allow create: if [float('NaN')] == [float('NaN')];
    }
    match /equalityIdentity/19/{id} {
      allow create: if [request.resource.data.n] == [1.0];
    }
    match /equalityIdentity/20/{id} {
      allow create: if [request.resource.data.n] == [1];
    }
    match /equalityIdentity/21/{id} {
      allow create: if [request.resource.data.f] == [1.5];
    }
    match /equalityIdentity/22/{id} {
      allow create: if {'a': 1}.values() == [1.0];
    }
  }
}

rulesets.duration-and-latlng:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /checkins/{checkinId} {
      allow create: if request.auth != null
        && latlng.value(request.resource.data.lat, request.resource.data.lng).latitude() >= -90
        && latlng.value(request.resource.data.lat, request.resource.data.lng).longitude() >= -180
        && latlng.value(request.resource.data.lat, request.resource.data.lng)
             .distance(latlng.value(0, 0)) >= 0
        && duration.time(1, 0, 0, 0) > duration.value(0, 's')
        && duration.abs(duration.value(-5, 's')) > duration.value(0, 's');
    }
    match /durationParts/{id} {
      allow create: if request.auth != null
        && duration.value(1500, 'ms').seconds() == 1
        && duration.value(1500, 'ms').nanos() == 500000000;
    }
  }
}

rulesets.error-absorption-and-or:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // error || true → true (absorbed) → ALLOW
    match /errOrTrueAllow/{id} {
      allow create: if request.resource.data.missing > 0 || true;
    }
    // true || error → true → ALLOW (JS-compatible direction, control)
    match /trueOrErrAllow/{id} {
      allow create: if true || request.resource.data.missing > 0;
    }
    // error || false → error propagates → DENY
    match /errOrFalseDeny/{id} {
      allow create: if request.resource.data.missing > 0 || false;
    }
    // error && false → false (absorbed) → DENY (as false, not error)
    match /errAndFalseDeny/{id} {
      allow create: if request.resource.data.missing > 0 && false;
    }
    // false && error → false → DENY (JS-compatible direction, control)
    match /falseAndErrDeny/{id} {
      allow create: if false && request.resource.data.missing > 0;
    }
    // error && true → error propagates → DENY
    match /errAndTrueDeny/{id} {
      allow create: if request.resource.data.missing > 0 && true;
    }
    // absorbed-error result feeds an outer || → ALLOW
    match /nestedAbsorbAllow/{id} {
      allow create: if (request.resource.data.missing > 0 && false) || true;
    }
    function overLimit0() {
      return true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && overLimit1();
    }
    function overLimit1() {
      return true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && overLimit2();
    }
    function overLimit2() {
      return true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && overLimit3();
    }
    function overLimit3() {
      return true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && overLimit4();
    }
    function overLimit4() {
      return true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && overLimit5();
    }
    function overLimit5() {
      return true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && overLimit6();
    }
    function overLimit6() {
      return true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && overLimit7();
    }
    function overLimit7() {
      return true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && overLimit8();
    }
    function overLimit8() {
      return true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && overLimit9();
    }
    function overLimit9() {
      return true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true && true;
    }
    // Allow rules after an error, in one match block.
    match /errThenTrueAllow/{id} {
      allow create: if [1] + [2] == [1, 2];
      allow create: if true;
    }
    match /errThenFalseDeny/{id} {
      allow create: if [1] + [2] == [1, 2];
      allow create: if false;
    }
    match /trueThenErrAllow/{id} {
      allow create: if true;
      allow create: if [1] + [2] == [1, 2];
    }
    match /falseThenErrDeny/{id} {
      allow create: if false;
      allow create: if [1] + [2] == [1, 2];
    }
    // The same shapes across two match blocks that both match the path.
    match /blocksErrThenTrueAllow/{id} {
      allow create: if [1] + [2] == [1, 2];
    }
    match /blocksErrThenTrueAllow/{id} {
      allow create: if true;
    }
    match /blocksErrThenFalseDeny/{id} {
      allow create: if [1] + [2] == [1, 2];
    }
    match /blocksErrThenFalseDeny/{id} {
      allow create: if false;
    }
    match /blocksTrueThenErrAllow/{id} {
      allow create: if true;
    }
    match /blocksTrueThenErrAllow/{id} {
      allow create: if [1] + [2] == [1, 2];
    }
    match /blocksFalseThenErrDeny/{id} {
      allow create: if false;
    }
    match /blocksFalseThenErrDeny/{id} {
      allow create: if [1] + [2] == [1, 2];
    }
    // A true rule past the limit after an error, and after a false rule.
    match /errThenOverLimitDeny/{id} {
      allow create: if [1] + [2] == [1, 2];
      allow create: if overLimit0();
    }
    match /falseThenOverLimitDeny/{id} {
      allow create: if false;
      allow create: if overLimit0();
    }
    // Errors passed into functions and let bindings.
    function ignoresArg(a) { return true; }
    function readsArg(a) { return a > 0; }
    function passesToIgnoresArg(a) { return ignoresArg(a); }
    function passesToReadsArg(a) { return readsArg(a); }
    function readsSecondArg(a, b) { return b; }
    function letUnread() { let x = 1 / request.resource.data.zero; return true; }
    function letRead() { let x = 1 / request.resource.data.zero; return x > 0; }
    match /argUnreadAllow/{id} {
      allow create: if ignoresArg(1 / request.resource.data.zero);
    }
    match /argReadDeny/{id} {
      allow create: if readsArg(1 / request.resource.data.zero);
    }
    match /argThroughTwoCallsUnreadAllow/{id} {
      allow create: if passesToIgnoresArg(1 / request.resource.data.zero);
    }
    match /argThroughTwoCallsReadDeny/{id} {
      allow create: if passesToReadsArg(1 / request.resource.data.zero);
    }
    match /argMissingFieldUnreadAllow/{id} {
      allow create: if ignoresArg(request.resource.data.missing);
    }
    match /letUnreadAllow/{id} {
      allow create: if letUnread();
    }
    match /letReadDeny/{id} {
      allow create: if letRead();
    }
    // Division and modulo by a zero read from data.
    match /divideByDataZeroDeny/{id} {
      allow create: if request.resource.data.one / request.resource.data.zero == 1;
    }
    match /moduloByDataZeroDeny/{id} {
      allow create: if request.resource.data.one % request.resource.data.zero == 1;
    }
    match /divideByDataZeroOrTrueAllow/{id} {
      allow create: if request.resource.data.one / request.resource.data.zero == 1 || true;
    }
    // Which of two errors is reported.
    match /firstErrorEq/{id} {
      allow create: if request.resource.data.missingA == request.resource.data.missingB;
    }
    match /firstErrorPlus/{id} {
      allow create: if request.resource.data.missingA + request.resource.data.missingB == 1;
    }
    match /firstErrorList/{id} {
      allow create: if [request.resource.data.missingA, request.resource.data.missingB] == [];
    }
    match /firstErrorMap/{id} {
      allow create: if {'a': request.resource.data.missingA, 'b': request.resource.data.missingB} == {};
    }
    match /firstErrorIn/{id} {
      allow create: if request.resource.data.missingA in [request.resource.data.missingB];
    }
    match /firstErrorMethodArgs/{id} {
      allow create: if request.resource.data.get(request.resource.data.missingA, request.resource.data.missingB) == 1;
    }
    match /firstErrorReceiver/{id} {
      allow create: if request.resource.data.missingA.get(request.resource.data.missingB, 1) == 1;
    }
    match /firstErrorFunctionArgs/{id} {
      allow create: if readsSecondArg(request.resource.data.missingA, request.resource.data.missingB);
    }
    // An operand past the limit after an error in the same expression.
    match /errThenOperandOverLimitDeny/{id} {
      allow create: if [request.resource.data.missing, overLimit0()] == [];
    }
  }
}

rulesets.functions-verbs-and-recursive:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isSignedIn() {
      return request.auth != null;
    }
    function roleLevel() {
      let base = isSignedIn() ? 1 : 0;
      let boosted = base * 2;
      return boosted;
    }
    function seated(game) {
      return game.players.size() == 2;
    }
    function inBounds(shot) {
      return shot.keys().hasOnly(['dx', 'dy']);
    }
    function relay(value) {
      return inBounds(value);
    }
    function boardHasOrigin() {
      let doc = request.resource.data;
      return doc.board.keys().hasAll(['a1']);
    }
    function boardKeepsZ() {
      return !('z' in request.resource.data.board.diff(resource.data.board).affectedKeys());
    }
    function headIsOnePart() {
      return request.resource.data.at.split('_')[0].split('-').size() == 1;
    }
    function tailHasTwoWords() {
      return 'a_b c'.split(request.resource.data.at)[1].split(' ').size() == 2;
    }
    match /docs/{docId} {
      allow get: if isSignedIn();
      allow list: if isSignedIn() && roleLevel() >= 2;
      allow update: if isSignedIn() && roleLevel() >= 2;
      allow write: if isSignedIn() && roleLevel() >= 2;
    }
    match /trees/{treeId}/{document=**} {
      allow read: if isSignedIn();
    }
    // a get() result passed as a parameter; the function calls a method on its field
    match /seated/{id} {
      allow create: if seated(get(/databases/$(database)/documents/lobbies/main).data);
    }
    // a method called directly on a field of a get() result
    match /getField/{id} {
      allow create: if get(/databases/$(database)/documents/lobbies/main).data.players.size() == 2;
    }
    // a map field passed as a parameter
    match /mapParam/{id} {
      allow create: if inBounds(request.resource.data.shot);
    }
    // a parameter passed on from one function to another
    match /relayed/{id} {
      allow create: if relay(request.resource.data.shot);
    }
    // a let bound to request data
    match /letDoc/{id} {
      allow create: if boardHasOrigin();
    }
    // a ternary whose branches are a map and a string; both support size()
    match /ternarySize/{id} {
      allow create: if (request.resource.data.useMap ? {'a': 1, 'b': 2} : 'ab').size() == 2;
    }
    // a ternary whose string branch does not support keys()
    match /ternaryKeys/{id} {
      allow create: if (request.resource.data.useMap ? {'a': 1} : 'a').keys().size() == 1;
    }
    // membership in a set computed from request and resource data
    match /diffKeys/{id} {
      allow update: if boardKeepsZ();
    }
    // a method on an element of a list split from a request string
    match /splitHead/{id} {
      allow create: if headIsOnePart();
    }
    // a method on an element of a literal split by a request string
    match /splitBy/{id} {
      allow create: if tailHasTwoWords();
    }
  }
}

rulesets.get-after-and-exists-after:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // getAfter on request target == request.resource.data
    match /getAfterTargetAllow/{id} {
      allow create: if request.auth != null
        && getAfter(request.path).data.x == request.resource.data.x;
    }
    // existsAfter on create is true
    match /existsAfterCreateAllow/{id} {
      allow create: if request.auth != null
        && existsAfter(request.path) == true;
    }
    // existsAfter on delete is false
    match /existsAfterDeleteAllow/{id} {
      allow delete: if request.auth != null
        && existsAfter(request.path) == false;
    }
    // existsAfter on unrelated mocked path uses exists()
    match /existsAfterMockAllow/{id} {
      allow create: if request.auth != null
        && existsAfter(/databases/$(database)/documents/other/x) == true;
    }
    // DENY witness — wrong existsAfter
    match /existsAfterWrongDeny/{id} {
      allow create: if request.auth != null
        && existsAfter(request.path) == false;
    }
  }
}

rulesets.get-missing-doc:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // get() of an unmocked (missing) doc → error → DENY
    match /getMissingDeny/{id} {
      allow create: if get(/databases/$(database)/documents/cfg/missing).data.flag == true;
    }
    // the pre-fix footgun: comparing missing get() to null must NOT allow
    match /getMissingNullProbeDeny/{id} {
      allow create: if get(/databases/$(database)/documents/cfg/missing) == null;
    }
    // missing-get error absorbed by || true (RULES-B3 interplay) → ALLOW
    match /getMissingAbsorbAllow/{id} {
      allow create: if get(/databases/$(database)/documents/cfg/missing).data.flag == true || true;
    }
    // exists() guard pattern with nothing mocked → false/error → DENY
    match /guardedGetDeny/{id} {
      allow create: if exists(/databases/$(database)/documents/cfg/missing)
        && get(/databases/$(database)/documents/cfg/missing).data.flag == true;
    }
    // mocked doc: data flows through → ALLOW
    match /getMockedAllow/{id} {
      allow create: if get(/databases/$(database)/documents/cfg/site).data.flag == true;
    }
    // mocked doc: production CANNOT express resource identity (.id) via a
    // function mock — the API returns "Property id is undefined on
    // object." → DENY. Kept as a documented witness of the limitation.
    match /getResourceIdAllow/{id} {
      allow create: if get(/databases/$(database)/documents/cfg/site).id == 'site';
    }
    // mocked doc: same limitation for __name__ — a mocked get() result has
    // no resource identity attached, so this also errors → DENY.
    match /getResourceNameAllow/{id} {
      allow create: if get(/databases/$(database)/documents/cfg/site).__name__
        == /databases/$(database)/documents/cfg/site;
    }
    // mocked exists() → ALLOW (control for the guard pattern)
    match /existsMockedAllow/{id} {
      allow create: if exists(/databases/$(database)/documents/other/x);
    }
  }
}

rulesets.globals-request-path-and-resource-id:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // request.path is path
    match /reqPathIsPathAllow/{id} {
      allow create: if request.auth != null
        && request.path is path;
    }
    // request.path equality with literal
    match /reqPathEqAllow/{id} {
      allow create: if request.auth != null
        && request.path == /databases/$(database)/documents/reqPathEqAllow/$(id);
    }
    // request.query is absent for non-list requests; reading it errors → DENY.
    match /reqQueryAllow/{id} {
      allow create: if request.auth != null
        && request.query is map
        && request.query.size() == 0;
    }
    // resource.id on a CREATE: production makes resource null (the target
    // doc does not exist pre-write), so resource.id errors and it DENYs.
    match /resourceIdOnCreateDeny/{id} {
      allow create: if request.auth != null
        && resource.id == id
        && resource.id is string;
    }
    // resource.__name__ on a CREATE: same, resource is null pre-write, so
    // resource.__name__ errors and it DENYs.
    match /resourceNameOnCreateDeny/{id} {
      allow create: if request.auth != null
        && resource.__name__ == request.path
        && resource.__name__ is path;
    }
    // DENY witness — wrong resource.id
    match /resourceIdWrongDeny/{id} {
      allow create: if request.auth != null
        && resource.id == 'definitelyNotThisId';
    }
  }
}

rulesets.hierarchical-match-cascade:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /parents/{parentId} {
      match /children/{childId} {
        allow get: if true;
      }
    }
    match /{path=**}/items/{id} {
      allow read: if request.auth != null;
    }
    match /{prefix=**}/tagged/{tagId} {
      allow get: if tagId == 'x1';
    }
    match /{group=**}/groups/{groupId} {
      match /members/{memberId} {
        allow get: if true;
      }
    }
    match /{document=**} {
      match /notes/{noteId} {
        allow get: if noteId == 'n1';
      }
    }
  }
}

rulesets.int-float-and-division:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // int ÷ int truncates: 10 / 4 == 2
    match /intDivTruncAllow/{id} {
      allow create: if 10 / 4 == 2;
    }
    // int ÷ int is NOT float division
    match /intDivNotFloatDeny/{id} {
      allow create: if 10 / 4 == 2.5;
    }
    // truncation is toward zero for negatives: -7 / 2 == -3
    match /negIntDivAllow/{id} {
      allow create: if -7 / 2 == -3;
    }
    // float division: 10.0 / 4.0 == 2.5
    match /floatDivAllow/{id} {
      allow create: if 10.0 / 4.0 == 2.5;
    }
    // mixed int/float promotes to float: 10 / 4.0 == 2.5
    match /mixedDivAllow/{id} {
      allow create: if 10 / 4.0 == 2.5;
    }
    // integer modulo: 10 % 3 == 1
    match /modAllow/{id} {
      allow create: if 10 % 3 == 1;
    }
    // division by zero is an error → DENY (not Infinity)
    match /divByZeroDeny/{id} {
      allow create: if 10 / 0 == 0;
    }
    // div-by-zero error absorbed by || true (RULES-B3 interplay) → ALLOW
    match /divByZeroAbsorbAllow/{id} {
      allow create: if 10 / 0 == 0 || true;
    }
    // wire int payload satisfies "is int", not float
    match /isIntAllow/{id} {
      allow create: if request.resource.data.n is int
        && !(request.resource.data.n is float);
    }
    // wire float payload satisfies "is float", not int
    match /isFloatAllow/{id} {
      allow create: if request.resource.data.x is float
        && !(request.resource.data.x is int);
    }
    // "is number" holds for an int and a float payload, not a string or null
    match /isNumber/{id} {
      allow create: if request.resource.data.v is number;
    }
    // ordering compares an int and a float by value, in both directions
    match /intFloatOrder/{id} {
      allow update: if request.resource.data.v > resource.data.v;
    }
  }
}

rulesets.list-and-string-methods:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /posts/{postId} {
      allow create: if request.auth != null
        && request.resource.data.categories.split(',').hasOnly(['news', 'tech', 'sport'])
        && request.resource.data.categories.split(',').hasAny(['news', 'tech'])
        && request.resource.data.categories.split(',').hasAll(['news'])
        && request.resource.data.tags.join(',').size() > 0
        && request.resource.data.slug.lower() == request.resource.data.slug
        && request.resource.data.title.trim().size() >= 3
        && request.resource.data.code.upper().size() == 4
        && request.resource.data.body.replace('  ', ' ').size() > 0
        && request.resource.data.values().size() >= 5;
    }
  }
}

rulesets.list-methods-concat-removeall-toset:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // concat — basic
    match /concatAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.a.concat(request.resource.data.b).size() == 4;
    }
    // concat — preserves order
    match /concatOrderAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.a.concat(['c'])[2] == 'c';
    }
    // concat — does NOT dedupe
    match /concatNoDedupAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.a.concat(['a','b']).size() == 4;
    }
    // removeAll — basic
    match /removeAllAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.a.removeAll(['b']).size() == 2;
    }
    // removeAll — removes all matching occurrences
    match /removeAllManyAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.a.removeAll(['b']).size() == 2;
    }
    // removeAll — empty arg → identity
    match /removeAllEmptyAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.a.removeAll([]).size() == 3;
    }
    // toSet — dedupes
    match /toSetAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.a.toSet().size() == 3;
    }
    // toSet — chains to Set.difference (5.1 + 5.2 wiring)
    match /toSetChainAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.a.toSet().difference(['a']).hasOnly(['b','c']);
    }
    // DENY witness — concat with wrong expected size
    match /concatDeny/{id} {
