rulesets.path-constructor-and-bind:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // path literal is path
    match /literalIsPathAllow/{id} {
      allow create: if request.auth != null
        && /databases/$(database)/documents/users/alice is path;
    }
    // path() builtin returns Path
    match /constructorIsPathAllow/{id} {
      allow create: if request.auth != null
        && path('users/alice') is path;
    }
    // Path equality across two constructions
    match /pathEqAllow/{id} {
      allow create: if request.auth != null
        && path('users/alice') == path('users/alice');
    }
    // Path inequality
    match /pathNeqAllow/{id} {
      allow create: if request.auth != null
        && path('users/alice') != path('users/bob');
    }
    // Path is NOT string / NOT map (typeName specificity)
    match /pathSpecificityAllow/{id} {
      allow create: if request.auth != null
        && !(path('a/b') is string)
        && !(path('a/b') is map);
    }
    // Path.bind substitutes placeholder
    match /bindAllow/{id} {
      allow create: if request.auth != null
        && path('users/{uid}').bind({'uid': 'alice'}) == path('users/alice');
    }
    // Path numeric index
    match /pathIndexAllow/{id} {
      allow create: if request.auth != null
        && path('users/alice')[1] == 'alice';
    }
    // path() rejects an already-constructed Path argument
    match /pathIdempotentAllow/{id} {
      allow create: if request.auth != null
        && path(path('users/alice')) == path('users/alice');
    }
    // DENY witness — wrong path equality
    match /wrongPathDeny/{id} {
      allow create: if request.auth != null
        && path('users/alice') == path('users/bob');
    }
  }
}

rulesets.prototype-chain-keys:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // proto method name is NOT a key → false → DENY
    match /protoInDeny/{id} {
      allow create: if 'toString' in request.resource.data;
    }
    // negated form → ALLOW
    match /protoNotInAllow/{id} {
      allow create: if !('toString' in request.resource.data)
        && !('constructor' in request.resource.data)
        && !('hasOwnProperty' in request.resource.data);
    }
    // a REAL field named toString IS a key → ALLOW
    match /realKeyInAllow/{id} {
      allow create: if 'toString' in request.resource.data
        && request.resource.data.toString == 'present';
    }
    // .constructor access on a map without that field → error → DENY
    match /constructorAccessDeny/{id} {
      allow create: if request.resource.data.constructor != null;
    }
    // keys() reflects own keys only → ALLOW
    match /keysOwnOnlyAllow/{id} {
      allow create: if !request.resource.data.keys().hasAny(['toString', 'constructor'])
        && request.resource.data.keys().hasOnly(['name']);
    }
    // negated membership over a value that is not a collection → error → DENY
    match /notInNull/{id} {
      allow create: if !('a' in request.resource.data.v);
    }
    match /notInString/{id} {
      allow create: if !('a' in request.resource.data.v);
    }
    match /notInInt/{id} {
      allow create: if !('a' in request.resource.data.v);
    }
    match /notInFloat/{id} {
      allow create: if !('a' in request.resource.data.v);
    }
    match /notInBool/{id} {
      allow create: if !('a' in request.resource.data.v);
    }
    // negated int key into a map → error → DENY
    match /intKeyNotInMap/{id} {
      allow create: if !(1 in request.resource.data.v);
    }
    // set membership tests elements, never object fields
    match /inSet/{id} {
      allow create: if 'a' in request.resource.data.v.toSet();
    }
    match /fieldNameNotInSet/{id} {
      allow create: if !('items' in request.resource.data.v.toSet());
    }
    // negated membership over a timestamp, a path or a map diff
    match /notInTimestamp/{id} {
      allow create: if !('a' in request.time);
    }
    match /notInPath/{id} {
      allow create: if !('a' in request.path);
    }
    match /notInMapDiff/{id} {
      allow create: if !('a' in request.resource.data.diff({}));
    }
  }
}

rulesets.range-slice-list-and-string:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    // List slice — mid range
    match /listMidAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.arr[1:3].size() == 2;
    }
    // List slice — value at slice index
    match /listValueAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.arr[1:3][0] == 'b';
    }
    // List slice — full length
    match /listFullAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.arr[0:4].size() == 4;
    }
    // List slice — i==j → empty
    match /listEmptyAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.arr[2:2].size() == 0;
    }
    // List slice — end OOB is an evaluation error
    match /listClampAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.arr[1:99].size() == 3;
    }
    // String slice — substring
    match /strSubAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.s[6:11] == 'world';
    }
    // String slice — prefix
    match /strPrefAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.s[0:5] == 'hello';
    }
    // String slice — empty (i==j)
    match /strEmptyAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.s[3:3] == '';
    }
    // String slice — end OOB is an evaluation error
    match /strClampAllow/{id} {
      allow create: if request.auth != null
        && request.resource.data.s[6:99] == 'world';
    }
    // DENY witness — list slice with wrong expected size
    match /listSliceDeny/{id} {
      allow create: if request.auth != null
        && request.resource.data.arr[0:2].size() == 5;
    }
    // Bounds: start must be an index, end - 1 must be an index, and start
    // must not exceed end.
    match /listZeroZero/{id} {
      allow create: if request.resource.data.arr[0:0].size() == 0;
    }
    match /listLenLen/{id} {
      allow create: if request.resource.data.arr[4:4].size() == 0;
    }
    match /listLastEmpty/{id} {
      allow create: if request.resource.data.arr[3:3].size() == 0;
    }
    match /listLastElement/{id} {
      allow create: if request.resource.data.arr[3:4] == ['d'];
    }
    match /listEndBeforeFirst/{id} {
      allow create: if request.resource.data.arr[1:0].size() == 0;
    }
    match /listStartAfterEnd/{id} {
      allow create: if request.resource.data.arr[3:1].size() == 0;
    }
    match /listEmptyZeroZero/{id} {
      allow create: if [][0:0] == [];
    }
    match /strZeroZero/{id} {
      allow create: if request.resource.data.s[0:0] == '';
    }
    match /strOneOne/{id} {
      allow create: if request.resource.data.s[1:1] == '';
    }
    match /strLastEmpty/{id} {
      allow create: if request.resource.data.s[4:4] == '';
    }
    match /strLenLen/{id} {
      allow create: if request.resource.data.s[5:5] == '';
    }
    match /strStartAfterEnd/{id} {
      allow create: if request.resource.data.s[2:1] == '';
    }
    match /strEmptyZeroZero/{id} {
      allow create: if ''[0:0] == '';
    }
  }
}

rulesets.required-fields-and-mapdiff:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /articles/{articleId} {
      // create: exact required field set, self-owned
      allow create: if request.auth != null
        && request.resource.data.keys().hasAll(['title', 'body', 'ownerId', 'tags'])
        && request.resource.data.keys().hasOnly(['title', 'body', 'ownerId', 'tags'])
        && request.resource.data.ownerId == request.auth.uid;
      // update: only title/body may change; ownerId immutable, no add/remove
      allow update: if request.auth != null
        && resource.data.ownerId == request.auth.uid
        && request.resource.data.diff(resource.data).affectedKeys().hasOnly(['title', 'body'])
        && request.resource.data.diff(resource.data).changedKeys().hasAny(['title', 'body'])
        && request.resource.data.diff(resource.data).addedKeys().size() == 0
        && request.resource.data.diff(resource.data).removedKeys().size() == 0
        && request.resource.data.diff(resource.data).unchangedKeys().hasAll(['ownerId']);
    }
    // keys() returns a List: each List method and type test on it
    match /keysToSet/{id} {
      allow create: if request.resource.data.keys().toSet() == ['a', 'b'].toSet();
    }
    match /keysHasAll/{id} {
      allow create: if request.resource.data.keys().hasAll(['a', 'b']);
    }
    match /keysSize/{id} {
      allow create: if request.resource.data.keys().size() == 2;
    }
    match /keysIndex/{id} {
      allow create: if request.resource.data.keys()[0] == 'a';
    }
    match /keysJoin/{id} {
      allow create: if request.resource.data.keys().join(',') == 'a';
    }
    match /keysHasAny/{id} {
      allow create: if request.resource.data.keys().hasAny(['a', 'z']);
    }
    match /keysHasOnly/{id} {
      allow create: if request.resource.data.keys().hasOnly(['a', 'b', 'c']);
    }
    match /keysIsList/{id} {
      allow create: if request.resource.data.keys() is list;
    }
    match /keysIsSet/{id} {
      allow create: if request.resource.data.keys() is set;
    }
    match /keysIsNotSet/{id} {
      allow create: if !(request.resource.data.keys() is set);
    }
    match /keysToSetSize/{id} {
      allow create: if request.resource.data.keys().toSet().size() == 2;
    }
    // Set equality on the MapDiff affectedKeys() Set: == against a Set or a
    // List, and hasAll() with hasOnly() against a List or a Set
    match /diffEqSet/{id} {
      allow update: if request.resource.data.diff(resource.data).affectedKeys() == ['b', 'a'].toSet();
    }
    match /diffEqList/{id} {
      allow update: if request.resource.data.diff(resource.data).affectedKeys() == ['a', 'b'];
    }
    match /diffBothWaysList/{id} {
      allow update: if request.resource.data.diff(resource.data).affectedKeys().hasAll(['b', 'a'])
        && request.resource.data.diff(resource.data).affectedKeys().hasOnly(['b', 'a']);
    }
    match /diffBothWaysSet/{id} {
      allow update: if request.resource.data.diff(resource.data).affectedKeys().hasAll(['b', 'a'].toSet())
        && request.resource.data.diff(resource.data).affectedKeys().hasOnly(['b', 'a'].toSet());
    }
    match /keyOrder/0/{id} {
      allow create: if {'b': 1, 'a': 2}.keys() == ['a', 'b'];
    }
    match /keyOrder/1/{id} {
      allow create: if {'b': 1, 'a': 2}.keys() == ['b', 'a'];
    }
    match /keyOrder/2/{id} {
      allow create: if {'b': 1, 'a': 2}.keys() != ['a', 'b'];
    }
    match /keyOrder/3/{id} {
      allow create: if {'b': 1, 'a': 2}.keys()[0] == 'a';
    }
    match /keyOrder/4/{id} {
      allow create: if {'b': 1, 'a': 2}.keys().join(',') == 'a,b';
    }
    match /keyOrder/5/{id} {
      allow create: if {'b': 1, 'B': 2, 'a': 3, 'A': 4, '10': 5, '2': 6, '1': 7, '_': 8, 'z': 9}.keys() == ['1', '10', '2', 'A', 'B', '_', 'a', 'b', 'z'];
