    match /sim6b/{id} {
      allow read: if {'a': 1}.get('a', 0, 99) == 1;
    }
    match /sim6c/{id} {
      allow read: if {'a': 1}.diff({'a': 1}, 'x').affectedKeys().size() == 0;
    }
    match /sim6d/{id} {
