      allow get: if '\u00e9'.size() == 2;
    }
    match /stringEscape/unicodeEscapeCjk/{id} {
      allow get: if '\u65e5\u672c' == '日本';
    }
    match /stringEscape/unicodeSurrogatePair/{id} {
