    }
    match /stringEscape/octalEscape/{id} {
      allow get: if '\101' == 'A' && '\101'.size() == 1 && '\012' == '\n';
    }
    match /stringEscape/octalEscapeMax/{id} {
      allow get: if '\377' == '\u00ff' && '\377' == '\xff' && '\377'.toUtf8().toHexString() == 'C3BF';
    }
