rulesets.time-math-and-casts:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /events/{eventId} {
      allow create: if request.auth != null
        && request.method == 'create'
        && request.time.year() >= 2020
        && request.time.month() >= 1
        && request.time.day() >= 1
        && request.time.hours() >= 0
        && request.time.minutes() >= 0
        && request.time.seconds() >= 0
        && request.time.nanos() >= 0
        && request.time.dayOfWeek() >= 1
        && request.time.dayOfYear() >= 1
        && request.time.toMillis() > 0
        && request.time.date() == request.time.date()
        && request.time.time() == request.time.time()
        && math.floor(request.resource.data.score) >= 0
        && math.round(request.resource.data.score) >= 0
        && math.sqrt(request.resource.data.area) >= 0
        && math.pow(request.resource.data.base, 2) >= 0
        && math.isNaN(request.resource.data.score) == false
        && int(request.resource.data.countStr) >= 0
        && float(request.resource.data.countStr) >= 0
        && string(request.resource.data.score).size() >= 1
        && request.resource.data.qty * 2 >= 2;
    }
    match /intFromString/{id} {
      allow create: if int('12') == 12 && int('-3') == -3 && int('+3') == 3 && int('-0') == 0 && int('12') is int;
    }
    match /intFromFloatTruncates/{id} {
      allow create: if int(1.9) == 1 && int(-1.9) == -1 && int(2.5) is int;
    }
    match /intFromFloatSaturates/{id} {
      allow create: if int(float('9.3e18')) == 9223372036854775807 && int(float('-9.3e18')) == -9223372036854775808 && int(float('NaN')) == 0;
    }
    match /intInt64Max/{id} {
      allow create: if int(9223372036854775807) == 9223372036854775807;
    }
    match /intDecimalString/{id} {
      allow create: if int('1.5') != 0;
    }
    match /intDecimalStringOrTrue/{id} {
      allow create: if (int('1.5') == 0) || true;
    }
    match /intHexString/{id} {
      allow create: if int('0x10') != 0;
    }
    match /intSurroundingSpaces/{id} {
      allow create: if int(' 1 ') != 1;
    }
    match /intExponentString/{id} {
      allow create: if int('1e3') != 0;
    }
    match /intOverflow/{id} {
      allow create: if int('9223372036854775808') != 0;
    }
    match /intBool/{id} {
      allow create: if int(true) != 0;
    }
    match /intBoolOrTrue/{id} {
      allow create: if (int(true) == 1) || true;
    }
    match /intNull/{id} {
      allow create: if int(null) != 0;
    }
    match /intTwoArgs/{id} {
      allow create: if int('1', 2) == 1;
    }
    match /floatStringForms/{id} {
      allow create: if float('1e3') == 1000.0 && float('.5') == 0.5 && float('5.') == 5.0 && float('1.5f') == 1.5 && float('1.5d') == 1.5 && float('0x1p3') == 8.0 && float(' 2.5') == 2.5 && float('2.5 ') == 2.5;
    }
    match /floatStringSpecial/{id} {
      allow create: if float('NaN') != float('NaN') && float('Infinity') > 1.0 && float('-Infinity') < 1.0;
    }
    match /floatFromNumbers/{id} {
      allow create: if float(2) is float && float(2) == 2.0 && float(1.5) is float && float(1.5) == 1.5;
    }
    match /floatInf/{id} {
      allow create: if float('inf') > 1.0;
    }
    match /floatLowercaseNan/{id} {
      allow create: if float('nan') != 0.0;
    }
    match /floatText/{id} {
      allow create: if float('abc') != 0.0;
    }
    match /floatTextOrTrue/{id} {
      allow create: if (float('abc') == 0.0) || true;
    }
    match /floatBool/{id} {
      allow create: if float(true) != 0.0;
    }
    match /floatNull/{id} {
      allow create: if float(null) != 0.0;
    }
    match /stringFromScalars/{id} {
      allow create: if string(true) == 'true' && string(null) == 'null' && string('s') == 's' && string(12) == '12' && string(path('a/b')) == '/a/b';
    }
    match /stringFromFloat/{id} {
      allow create: if string(1.0) == '1.0' && string(float(2)) == '2.0' && string(0.1 + 0.2) == '0.30000000000000004' && string(1.0 / 3.0) == '0.3333333333333333' && string(-0.0) == '-0.0';
    }
    match /stringFromFloatScientific/{id} {
      allow create: if string(float('1e7')) == '1.0E7' && string(float('1e-4')) == '1.0E-4' && string(123456789.0) == '1.23456789E8' && string(float('1e21')) == '1.0E21' && string(float('2e-3')) == '0.002' && string(float('NaN')) == 'NaN' && string(float('-Infinity')) == '-Infinity';
    }
    match /stringFromFloatSubnormal/{id} {
      allow create: if string(float('4.9e-324')) == '4.9E-324' && string(float('-4.9e-324')) == '-4.9E-324' && string(float('1e-323')) == '9.9E-324' && string(float('2e-323')) == '2.0E-323' && string(float('1e-322')) == '9.9E-323' && string(float('1e-310')) == '1.0E-310';
    }
    match /stringFromFloatSubnormalNot/{id} {
      allow create: if string(float('4.9e-324')) != '4.9E-324';
    }
    match /stringFromFloatSubnormalShortest/{id} {
      allow create: if string(float('4.9e-324')) == '5.0E-324';
    }
    match /stringFromList/{id} {
      allow create: if string([1]) != '';
    }
    match /stringFromListOrTrue/{id} {
      allow create: if (string([1]) == '') || true;
    }
    match /stringFromMap/{id} {
      allow create: if string({'a': 1}) != '';
    }
    match /stringFromBytes/{id} {
      allow create: if string(b'abc') != '';
    }
    match /stringFromDuration/{id} {
      allow create: if string(duration.value(1, 's')) != '';
    }
    match /mathAbsInt64Min/{id} {
      allow create: if math.abs(-9223372036854775807 - 1) < 0 && math.abs(-9223372036854775807 - 1) == -9223372036854775807 - 1;
    }
    match /mathAbsKeepsType/{id} {
      allow create: if math.abs(-2) == 2 && math.abs(-2) is int && math.abs(1) is int && math.abs(-2.5) == 2.5 && math.abs(-2.5) is float && math.abs(-1.0) is float;
    }
    match /mathCeilFloorFloat/{id} {
      allow create: if math.ceil(1.5) == 2 && math.ceil(1.5) is float && math.ceil(-1.5) == -1 && math.ceil(-0.5) == 0 && math.floor(-1.5) == -2 && math.floor(2.5) == 2 && math.floor(-0.5) == -1 && math.floor(1) is float && math.ceil(1) is float;
    }
    match /mathCeilIsInt/{id} {
      allow create: if math.ceil(1.5) is int;
    }
    match /mathRoundHalfUpInt/{id} {
      allow create: if math.round(2.5) == 3 && math.round(-2.5) == -2 && math.round(-1.5) == -1 && math.round(0.5) == 1 && math.round(-0.5) == 0 && math.round(1.4) == 1 && math.round(2.5) is int && math.round(1) is int;
    }
    match /mathRoundHalfAwayFromZero/{id} {
      allow create: if math.round(-2.5) == -3;
    }
    match /mathRoundIsFloat/{id} {
      allow create: if math.round(2.5) is float;
    }
    match /mathRoundNaNInfinity/{id} {
      allow create: if math.round(math.sqrt(-1)) == 0 && math.round(math.pow(0, -1)) > 0;
    }
    match /mathSqrtPowFloat/{id} {
      allow create: if math.sqrt(4) == 2.0 && math.sqrt(4) is float && math.sqrt(2) > 1.414 && math.sqrt(2) < 1.415 && math.pow(2, 3) == 8.0 && math.pow(2, 3) is float && math.pow(2, -1) == 0.5 && math.pow(4, 0.5) == 2.0;
    }
    match /mathNaNInfinity/{id} {
      allow create: if math.isNaN(math.sqrt(-1)) && !math.isNaN(1) && !math.isNaN(1.0) && !math.isNaN(math.pow(0, -1)) && math.pow(0, -1) > 1000000000.0;
    }
    match /mathAbsString/{id} {
      allow create: if !(math.abs('a') == 1);
    }
    match /mathAbsStringOrTrue/{id} {
      allow create: if (math.abs('a') == 1) || true;
    }
    match /mathAbsBool/{id} {
      allow create: if !(math.abs(true) == 1);
    }
    match /mathAbsNull/{id} {
      allow create: if !(math.abs(null) == 1);
    }
    match /mathCeilString/{id} {
      allow create: if !(math.ceil('a') == 1);
    }
    match /mathSqrtString/{id} {
      allow create: if !(math.sqrt('a') == 1);
    }
    match /mathPowString/{id} {
      allow create: if !(math.pow(2, 'a') == 1);
    }
    match /mathIsNaNString/{id} {
      allow create: if !math.isNaN('a');
    }
    match /mathAbsTwoArgs/{id} {
      allow create: if !(math.abs(1, 2) == 1);
    }
    match /mathSqrtNoArgs/{id} {
      allow create: if !(math.sqrt() == 1);
    }
    match /mathIsInfinite/{id} {
      allow create: if math.isInfinite(1.0) == false;
    }
    match /mathIsInfiniteOrTrue/{id} {
      allow create: if math.isInfinite(1.0) || true;
    }
    match /mathIsInfiniteAndFalse/{id} {
      allow create: if !(math.isInfinite(1.0) && false);
    }
  }
}

rulesets.timestamp-component-accessors:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /seconds-of-minute/{id} {
      allow get: if request.time.seconds() == 30;
    }
    match /epoch-seconds/{id} {
      allow get: if request.time.seconds() == 1749995130;
    }
    match /nanos-of-second/{id} {
      allow get: if request.time.nanos() == 250000000;
    }
    match /to-millis/{id} {
      allow get: if request.time.toMillis() == 1749995130250;
    }
