    match /paListLengthNe/{id} {
      allow get: if resource.data.l.length != 99;
    }
    match /paListLengthNot/{id} {
      allow get: if !(resource.data.l.length == 2);
    }
    match /paListLengthOrTrue/{id} {
      allow get: if resource.data.l.length == 2 || true;
    }
